/* Один полный круг — одно окончательное решение. История не обнуляется при перерисовке. */
let resolveLapChoice=null,resumingMovement=false;
function pendingLapEnergy(){return game.lapEnergyEvents?.find(e=>e.state==='pending')||null}
function createLapEnergyEvent(level,lap){ensureRun();game.lapEnergyEvents||=[];const id=`${game.runId}:lap-energy:${level}:${lap}`;let event=game.lapEnergyEvents.find(e=>e.id===id);if(!event){event={id,level,lap,offered:1,state:'pending',credited:false,createdAt:new Date().toISOString()};game.lapEnergyEvents.push(event)}return event}
function offerLapEnergy(event){if(event.state!=='pending')return Promise.resolve();playSound('screenTransition');showModal('Маленькое открытие','ПОЛНЫЙ КРУГ ПРОЙДЕН',`<div class="lap-energy-light" aria-hidden="true">ϟ</div><h3 class="lap-energy-amount">+1 ⚡ ЭНЕРГИЯ</h3><p>Ты прошла полный круг. Ты можешь принять полученную энергию и добавить ее к энергии своего текущего пути.</p>`,[{label:'ПРИНЯТЬ +1 ⚡',action:()=>decideLapEnergy(event.id,'accepted')},{label:'ОТКАЗАТЬСЯ',secondary:true,action:()=>decideLapEnergy(event.id,'declined')}]);ge('game-modal').dataset.lapEvent=event.id;ge('modal-close').hidden=true;return new Promise(resolve=>{resolveLapChoice=resolve})}
function decideLapEnergy(id,choice){const event=game.lapEnergyEvents?.find(e=>e.id===id);if(!event||event.state!=='pending'||!['accepted','declined'].includes(choice))return false;ge('modal-buttons').querySelectorAll('button').forEach(b=>b.disabled=true);event.state=choice;event.decidedAt=new Date().toISOString();if(choice==='accepted'&&!event.credited){event.credited=true;game.energy++;game.energyHistory.push({kind:'earned',level:event.level,amount:1,source:'Полный круг',eventId:id,at:event.decidedAt})}persist();ge('game-modal').hidden=true;delete ge('game-modal').dataset.lapEvent;ge('modal-close').hidden=false;modalOpen=false;renderGame();if(typeof awardLapCrystal==='function')awardLapCrystal(event.level,event.lap);if(choice==='accepted'){playSound('energyGain');energyFlight(1);pulseEnergy();announce('Принято +1 ⚡ энергии.')}else announce('Ты решила не принимать эту энергию.');const done=resolveLapChoice;resolveLapChoice=null;done?.();return true}
async function resumeGameMovement(){if(resumingMovement||moving||(!game.pendingMovement&&!pendingLapEnergy()&&!game.pendingRoll&&!game.pendingCardCompletion))return;resumingMovement=true;moving=true;renderGame();try{const event=pendingLapEnergy();if(event)await offerLapEnergy(event);if(game.pendingMovement)await moveSteps(game.pendingMovement.remaining,true);moving=false;pendingPortal=!!game.portalReached&&canPassPortal();if(game.pendingRoll)completeDiceTurn();else if(game.pendingCardCompletion){const pending=game.pendingCardCompletion;let card=cardManifest[pending.deck]?.find(c=>c.id===pending.id);for(let retry=0;!card&&retry<40;retry++){await delay(100);card=cardManifest[pending.deck]?.find(c=>c.id===pending.id)}if(card)await acceptCard(card,true);else showModal('Продолжение сохранено','Карта пока не загрузилась','<p>Выбор энергии сохранен. Обнови страницу, чтобы продолжить действие карты.</p>',[{label:'ОБНОВИТЬ',action:()=>location.reload()}])}}finally{moving=false;resumingMovement=false;persist();renderGame()}}
setTimeout(()=>{if(game.pendingMovement||pendingLapEnergy()||game.pendingRoll||game.pendingCardCompletion){ge('journey-cinema').hidden=true;SoundManager.stop('intro');resumeGameMovement()}},0);
